// Generates src/protocol.generated.ts from calu's JSON Schema (`uv run calu protocol`).
//
// Usage (from extensions/vscode, on Linux):  npm run gen:protocol
// Optional: CALU_SCHEMA_FILE=<file> reads the schema from a file instead of running uv.
//
// Output: one TypeScript interface per model in the schema's `$defs`, plus the maps
// `RequestParams`, `RequestResults`, `EventParams` (method name -> type) and the
// `PROTOCOL_VERSION` constant. The generated file is committed; rerun after protocol changes.

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

const here = dirname(fileURLToPath(import.meta.url));
const extensionDir = join(here, '..');
const repoRoot = join(extensionDir, '..', '..');

/**
 * Read the protocol schema document.
 *
 * @returns The parsed schema object with the keys `version`, `requests`, `events`, `results`
 *   and `$defs` (see `src/calu/protocol/schema.py`).
 * @throws Error if `uv run calu protocol` fails or prints invalid JSON.
 */
function readSchema() {
  if (process.env.CALU_SCHEMA_FILE) {
    return JSON.parse(readFileSync(process.env.CALU_SCHEMA_FILE, 'utf8'));
  }
  const text = execFileSync('uv', ['run', '--project', repoRoot, 'calu', 'protocol'], {
    cwd: repoRoot,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'inherit'],
  });
  return JSON.parse(text);
}

/**
 * Remove `title` keys from property schemas, so that json-schema-to-typescript does not emit a
 * type alias per titled property (e.g. `type AgentId = string`). Model titles stay.
 *
 * @param node Any JSON value of the schema; modified in place.
 * @param isModel True if `node` is a model definition (its own `title` is kept).
 * @returns Nothing.
 */
function stripPropertyTitles(node, isModel = false) {
  if (Array.isArray(node)) {
    node.forEach((child) => stripPropertyTitles(child));
    return;
  }
  if (node === null || typeof node !== 'object') return;
  if (!isModel) delete node.title;
  for (const [key, value] of Object.entries(node)) {
    if (key === '$defs') {
      for (const def of Object.values(value)) stripPropertyTitles(def, true);
    } else {
      stripPropertyTitles(value);
    }
  }
}

/**
 * Return the model name of a `{"$ref": "#/$defs/Name"}` object.
 *
 * @param ref A schema object with a `$ref` into `$defs`.
 * @returns The model name, e.g. "ChatSendParams".
 */
function refName(ref) {
  return ref.$ref.split('/').pop();
}

/**
 * Render a TypeScript interface that maps method names to model types.
 *
 * @param name Interface name.
 * @param map Object of method name -> `$ref` object.
 * @param doc Doc comment text.
 * @returns TypeScript source text.
 */
function methodMap(name, map, doc) {
  const lines = Object.entries(map).map(([method, ref]) => `  '${method}': ${refName(ref)};`);
  return `/** ${doc} */\nexport interface ${name} {\n${lines.join('\n')}\n}\n`;
}

const schema = readSchema();
const defs = schema.$defs;
stripPropertyTitles({ $defs: defs });

// One root object that references every model, so that all of them are emitted.
const root = {
  title: 'CaluProtocolModels',
  type: 'object',
  properties: Object.fromEntries(Object.keys(defs).map((n) => [n, { $ref: `#/$defs/${n}` }])),
  additionalProperties: false,
  $defs: defs,
};

let ts = await compile(root, 'CaluProtocolModels', {
  bannerComment: '',
  additionalProperties: false,
  declareExternallyReferenced: true,
  unreachableDefinitions: true,
  strictIndexSignatures: true,
  format: true,
});
// Drop the generator's "referenced by" boilerplate from doc comments.
ts = ts.replace(/\n \*\n \* This interface was referenced by `CaluProtocolModels`'s JSON-Schema\n \* via the `definition` "\w+"\./g, '');
ts = ts.replace(/\/\*\*\n \* This interface was referenced by `CaluProtocolModels`'s JSON-Schema\n \* via the `definition` "\w+"\.\n \*\/\n/g, '');
// The root interface only exists to reach every model; drop it.
ts = ts.replace(/export interface CaluProtocolModels \{[\s\S]*?\n\}\n/, '');

const out = [
  '// GENERATED by scripts/gen-protocol.mjs from `uv run calu protocol`. Do not edit by hand;',
  '// run `npm run gen:protocol` after changing src/calu/protocol/messages.py.',
  '/* eslint-disable */',
  '',
  `/** Protocol version of the calu version this file was generated from. */`,
  `export const PROTOCOL_VERSION = ${JSON.stringify(schema.version)};`,
  '',
  ts.trim(),
  '',
  methodMap('RequestParams', schema.requests, 'Request method -> type of its `params`.'),
  methodMap(
    'RequestResults',
    schema.results,
    'Request method -> type of its `result` (requests not listed here return `{}` or a small object).',
  ),
  methodMap('EventParams', schema.events, 'Event (notification) method -> type of its `params`.'),
  '/** Name of a request method. */',
  'export type RequestMethod = keyof RequestParams;',
  '/** Name of an event method. */',
  'export type EventMethod = keyof EventParams;',
  '',
].join('\n');

writeFileSync(join(extensionDir, 'src', 'protocol.generated.ts'), out);
console.log('wrote src/protocol.generated.ts');
